    imageHint: "Rolling green hills of Nyika Plateau with zebras",
    descriptionAdvanced: {
      de: "Der Nyika-Nationalpark ist Malawis ältester und größter Nationalpark und bedeckt fast das gesamte Nyika-Plateau im Norden des Landes. Auf einer durchschnittlichen Höhe von etwa 2.100 Metern bietet der Park eine für Afrika ungewöhnliche Landschaft, die an die schottischen Highlands erinnert. Statt dichter Savanne dominieren sanft geschwungene Grashügel und ausgedehnte Hochlandsteppen das Bild. Botanisch ist die Region von herausragender Bedeutung, da hier über 200 verschiedene Orchideenarten heimisch sind, von denen viele nirgendwo sonst auf der Welt vorkommen. Die Tierwelt ist ebenso faszinierend: Große Herden von Zebras, Eland-Antilopen und die seltene Pferdeantilope streifen durch die offenen Ebenen. Nyika gilt zudem als eines der besten Gebiete in Zentralafrika, um Leoparden in ihrer natürlichen Umgebung zu beobachten, besonders während der kühleren Dämmerungsstunden.",
      hu: "A Nyika Nemzeti Park Malawi legrégebbi és legnagyobb kiterjedésű védett területe, amely az ország északi részén elterülő hatalmas Nyika-fennsíkot foglalja magában. Az átlagosan 2100 méter tengerszint feletti magasságban fekvő park tájképe egészen egyedülálló Afrikában: a végtelen, hullámzó füves dombok és a hűvös hegyvidéki éghajlat inkább a skót felföldet idézi, mint a klasszikus szavannát. A botanikusok számára igazi paradicsom, hiszen több mint 200 vadon élő orchideafajnak ad otthont, amelyek jelentős része endemikus. Az állatvilág képviselői közül kiemelkednek a nagy létszámú zebra- és antilopcsordák, különösen a jávorantilopok és a fakó antilopok. A terület híres sűrű leopárdpopulációjáról is, amelyeket az éjszakai szafarik során gyakran meg lehet pillantani a nyílt fennsíkon barangolva.",
      ro: "Parcul Național Nyika este cel mai vechi și cel mai extins parc din Malawi, acoperind cea mai mare parte a platoului cu același nume din nordul țării. Situat la o altitudine medie de peste 2.100 de metri, parcul oferă un peisaj montan atipic pentru Africa, asemănător cu dealurile scoțiene, dominat de pajiști vaste și văi adânci. Această regiune este un sanctuar botanic de importanță mondială, adăpostind peste 200 de specii de orhidee sălbatice, multe dintre ele fiind endemice. Fauna este adaptată climatului răcoros, parcul fiind celebru pentru populațiile mari de zebre, antilope Eland și antilope roan care pasc pe platourile deschise. Nyika este considerat, de asemenea, unul dintre cele mai bune locuri din Africa Centrală pentru observarea leopardului, densitatea acestor prădători fiind remarcabilă în raport cu suprafața parcului.",
      en: "Nyika National Park is Malawi's oldest and largest protected area, encompassing nearly the entire Nyika Plateau in the northern highlands. At an average elevation of 2,100 meters, the landscape is strikingly different from the rest of Africa, featuring rolling montane grasslands and granite outcrops that closely resemble the Scottish Highlands. The park is a botanical treasure trove, home to over 200 species of wild orchids, several of which are unique to this specific plateau. Wildlife enthusiasts are drawn here to see large herds of Burchell's zebra, eland, and roan antelope roaming the open plains. Furthermore, Nyika is renowned for having one of the highest densities of leopards in Central Africa, offering visitors a rare chance to spot these elusive cats during evening game drives across the windswept and misty landscape.",
      es: "El Parque Nacional Nyika, en el norte de Malawi, fue fundado en 1965 y es el área protegida más grande del país. Se encuentra en una meseta a 2.000 metros de altura y es conocido por sus paisajes de praderas y bosques únicos. El parque alberga una fauna diversa, incluyendo cebras, antílopes y leopardos. Nyika es también un paraíso para los observadores de aves con más de 400 especies. El paisaje está marcado por flores silvestres, especialmente orquídeas. El parque ofrece rutas de senderismo y ciclismo de montaña.",
      pt: "O Parque Nacional de Nyika, no norte do Malawi, foi fundado em 1965 e é a maior área protegida do país. Situa-se num planalto a 2.000 metros de altitude e é conhecido pelas suas paisagens de pastagens e florestas únicas. O parque abriga uma fauna diversa, incluindo zebras, antílopes e leopardos. Nyika é também um paraíso para os observadores de aves com mais de 400 espécies. A paisagem é marcada por flores silvestres, especialmente orquídeas. O parque oferece trilhos de caminhada e BTT.",
      fr: "Le parc national de Nyika, dans le nord du Malawi, a été fondé en 1965 et est la plus grande zone protégée du pays. Situé sur un plateau à 2 000 mètres d'altitude, il est réputé pour ses prairies et ses forêts uniques. Le parc abrite une faune diversifiée, notamment des zèbres, des antilopes et des léopards. Nyika est aussi un paradis pour les ornithologues avec plus de 400 espèces. Le paysage est fleuri de fleurs sauvages, particulièrement d'orchidées. Le parc propose des randonnées à pied et en VTT.",
    },
