      hu: ["1970-ben alapították", "Terület: 2 300 km²", "Elefántok: 180", "Kudu antilop: 500", "Madárfajok: 280", "Orvvadászat csökkenés: 50% 2010 óta"],
      ro: ["Fondat în 1970", "Suprafață: 2.316 km²", "Elefanți: 200", "Antilope sable: 400", "Specii de păsări: 300", "Acoperire de pădure: 70%"],
      en: ["Established 1970", "Area: 2,316 km²", "Elephant population: 200", "Sable antelope: 500", "Bird species: 300", "Miombo cover: 75%"],
      es: ["Fundado en 1970", "Superficie: 2.316 km²", "Población de elefantes: 200", "Antílopes: 1.000", "Especies de aves: 300", "Cobertura de bosque Miombo: 70%"],
