      pt: ["Primeiro parque nacional de água doce do mundo.", "Abriga mais de 1.000 espécies de peixes.", "Conhecido pelo colorido ciclídeo Mbuna.", "Inclui áreas terrestres e ilhas no lago."],
      fr: ["Premier parc national d'eau douce au monde.", "Abrite plus de 1 000 espèces de poissons.", "Connu pour le cichlidé coloré Mbuna.", "Comprend des zones terrestres et des îles dans le lac."],
