      ro: ["Fondată în 1975", "Suprafață: 1.000 km²", "Hipopotami: 1.000", "Elefanți: 500", "Crocodili: 300", "Specii de păsări: 400"],
      en: ["Established 1975", "Area: 1,000 km²", "Hippos: 1,000", "Elephants: 500", "Crocodiles: 300", "Bird species: 400"],
