      de: ["Durchschnittliche Höhe von 1.500 Metern.", "Bekannt für reiche Orchideenbestände.", "Wichtiger Lebensraum für Greifvögel.", "Bietet Panoramablicke über das Umland."],
      hu: ["Átlagos magassága 1500 méter.", "Gazdag orchideaállományáról nevezetes.", "A ragadozó madarak fontos élőhelye.", "Panorámás kilátást nyújt a környékre."],
