      en: ["Established 1922", "Area 2,000 ha", "Over 100 bird species", "Endemic orchids", "Water catchment for villages", "Regulated timber extraction"],
      es: ["Fundada en 1922", "Superficie 2.000 hectáreas", "Más de 100 especies de aves", "Orquídeas endémicas", "Cuenca hídrica para aldeas", "Tala regulada"],
      pt: ["Fundada em 1922", "Área 2.000 hectares", "Mais de 100 espécies de aves", "Orquídeas endémicas", "Bacia hidrográfica para aldeias", "Exploração madeireira regulada"],
