      es: ["Segundo lago más grande del país.", "Conocido por periodos de desecación.", "Humedal protegido Ramsar desde 1997.", "Sustenta grandes colonias de aves acuáticas."],
      pt: ["Segundo maior lago do país.", "Conhecido por períodos de seca periódica.", "Zona húmida protegida Ramsar desde 1997.", "Sustenta grandes colónias de aves aquáticas."],
