      hu: "A Senga-öböl jelentős ökológiai helyszín a Malawi-tó partján. A terület erdőmaradványokat és gazdag halállományt foglal magában.",
      ro: "Senga Bay este un sit ecologic important pe malul Lacului Malawi. Zona include resturi de pădure și resurse piscicole bogate.",
      en: "Senga Bay is a significant ecological site on the shores of Lake Malawi. The area includes forest patches and rich fish populations.",
